CREATE TABLE `cube-srv-gen-maintain`.`fault_order` (
     `id` bigint(20) NOT NULL COMMENT '主键',
     `process_ins_id` varchar(64) NOT NULL COMMENT '流程实例id',
     `code` varchar(100) DEFAULT NULL COMMENT '故障单编号',
     `name` varchar(100) DEFAULT NULL COMMENT '故障单名称',
     `obj_id` bigint(20) DEFAULT NULL COMMENT '故障对象id',
     `obj_name` varchar(100) DEFAULT NULL COMMENT '故障对象名称',
     `obj_type` varchar(100) DEFAULT NULL COMMENT '故障对象类型',
     `fault_type_id` bigint(20) DEFAULT NULL COMMENT '故障类型id',
     `source` varchar(100) DEFAULT NULL COMMENT '故障来源',
     `urgency_level` varchar(100) DEFAULT NULL COMMENT '紧急程度',
     `result` varchar(100) DEFAULT NULL COMMENT '处理结果',
     `submit_time` datetime DEFAULT NULL COMMENT '提交时间',
     `submit_staff` varchar(100) DEFAULT NULL COMMENT '提交人',
     `cost` decimal(10,2) DEFAULT NULL COMMENT '维护成本',
     `state` varchar(100) DEFAULT NULL COMMENT '状态',
     `tenant` int(10) DEFAULT NULL COMMENT '租户编号',
     `deleted` bigint(20) DEFAULT NULL COMMENT '是否删除',
     `create_by` varchar(100) DEFAULT NULL COMMENT '创建用户',
     `create_time` datetime DEFAULT NULL COMMENT '创建时间',
     `update_by` varchar(100) DEFAULT NULL COMMENT '更新用户',
     `update_time` datetime DEFAULT NULL COMMENT '更新时间',
     PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC comment '故障单2.0';


alter table `cube-srv-gen-maintain`.`inspect_record_to_business` modify column  `business_id` varchar(64) DEFAULT NULL COMMENT '业务ID';

CREATE TABLE `cube-srv-gen-maintain`.`hidden_danger_new` (
     `id` bigint(20) unsigned NOT NULL COMMENT '主键',
     `process_ins_id` varchar(64) NOT NULL COMMENT '流程实例id',
     `code` varchar(100) DEFAULT NULL COMMENT '隐患单号',
     `name` varchar(100) DEFAULT NULL COMMENT '隐患单名称',
     `hidden_obj_id` bigint(20) unsigned DEFAULT NULL COMMENT '隐患对象id',
     `hidden_obj_name` varchar(100) DEFAULT NULL COMMENT '隐患对象名称',
     `hidden_obj_type` varchar(100) DEFAULT NULL COMMENT '隐患对象类型',
     `hidden_type_id` bigint(20) DEFAULT NULL COMMENT '隐患类型id',
     `source` varchar(100) DEFAULT NULL COMMENT '隐患来源',
     `remark` varchar(256) DEFAULT NULL COMMENT '隐患描述',
     `urgency_level` bigint(20) DEFAULT NULL COMMENT '隐患程度',
     `result` varchar(100) DEFAULT NULL COMMENT '处理结果',
     `submit_time` datetime DEFAULT NULL COMMENT '提交时间',
     `submit_staff` varchar(100) DEFAULT NULL COMMENT '提交人',
     `state` varchar(100) DEFAULT NULL COMMENT '状态',
     `tenant` int(10) DEFAULT NULL COMMENT '租户编号',
     `response` tinyint DEFAULT 0 COMMENT '是否响应',
     `deleted` bigint(20) unsigned DEFAULT NULL COMMENT '是否删除',
     `create_by` varchar(100) DEFAULT NULL COMMENT '创建用户',
     `create_time` datetime DEFAULT NULL COMMENT '创建时间',
     `update_by` varchar(100) DEFAULT NULL COMMENT '更新用户',
     `update_time` datetime DEFAULT NULL COMMENT '更新用户',
     PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT '隐患单2.0';



